import{_ as t,c as a,o as i,a2 as h}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 2.7 – Phân Loại Mạng Máy Tính","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.7-phan-loai-mang.md","filePath":"chuong-2/2.7-phan-loai-mang.md","lastUpdated":1775298873000}'),o={name:"chuong-2/2.7-phan-loai-mang.md"};function r(s,n,g,l,e,c){return i(),a("div",null,[...n[0]||(n[0]=[h(`<h1 id="muc-2-7-–-phan-loai-mang-may-tinh" tabindex="-1">Mục 2.7 – Phân Loại Mạng Máy Tính <a class="header-anchor" href="#muc-2-7-–-phan-loai-mang-may-tinh" aria-label="Permalink to &quot;Mục 2.7 – Phân Loại Mạng Máy Tính&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-phai-phan-loai-mang" tabindex="-1">Tại sao phải phân loại mạng? <a class="header-anchor" href="#tai-sao-phai-phan-loai-mang" aria-label="Permalink to &quot;Tại sao phải phân loại mạng?&quot;">​</a></h3><p>Hãy nghĩ đến hệ thống đường giao thông: Có đường làng (nhỏ, trong thôn), đường huyện (liên xã), đường quốc lộ (liên tỉnh), đường cao tốc (liên vùng), đường hàng không quốc tế. Mỗi loại đường có quy mô, tốc độ, và mục đích khác nhau.</p><p>Mạng máy tính cũng vậy – từ mạng kết nối vài thiết bị trong phòng, đến mạng toàn cầu kết nối hàng tỷ máy tính. Việc phân loại giúp:</p><ul><li><strong>Hiểu rõ phạm vi và mục đích</strong> của từng loại mạng.</li><li><strong>Chọn đúng công nghệ và thiết bị</strong> khi thiết kế mạng.</li><li><strong>Quản lý và bảo mật</strong> phù hợp với từng loại.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-phan-loai-theo-pham-vi-đia-ly" tabindex="-1">2.1 Phân loại theo phạm vi địa lý <a class="header-anchor" href="#_2-1-phan-loai-theo-pham-vi-đia-ly" aria-label="Permalink to &quot;2.1 Phân loại theo phạm vi địa lý&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại mạng</th><th>Tên đầy đủ</th><th>Phạm vi</th><th>Ví dụ điển hình</th></tr></thead><tbody><tr><td><strong>PAN</strong></td><td>Personal Area Network</td><td>Vài mét</td><td>Tai nghe Bluetooth, smartwatch</td></tr><tr><td><strong>LAN</strong></td><td>Local Area Network</td><td>Tòa nhà, khuôn viên</td><td>Mạng văn phòng, mạng trường học</td></tr><tr><td><strong>MAN</strong></td><td>Metropolitan Area Network</td><td>Thành phố, tỉnh</td><td>Mạng cáp truyền hình thành phố</td></tr><tr><td><strong>WAN</strong></td><td>Wide Area Network</td><td>Quốc gia, toàn cầu</td><td>Internet, mạng ngân hàng toàn quốc</td></tr></tbody></table><h3 id="_2-2-pan-–-mang-ca-nhan-personal-area-network" tabindex="-1">2.2 PAN – Mạng cá nhân (Personal Area Network) <a class="header-anchor" href="#_2-2-pan-–-mang-ca-nhan-personal-area-network" aria-label="Permalink to &quot;2.2 PAN – Mạng cá nhân (Personal Area Network)&quot;">​</a></h3><p><strong>PAN</strong> là mạng kết nối các thiết bị <strong>trong phạm vi cá nhân</strong> (vài mét xung quanh người dùng).</p><p><strong>Đặc điểm:</strong></p><ul><li>Phạm vi cực ngắn: thường <strong>dưới 10 mét</strong>.</li><li>Kết nối các thiết bị cá nhân của <strong>một người</strong>.</li><li>Công nghệ chủ yếu: <strong>Bluetooth</strong>, USB, ZigBee, NFC.</li><li>Không cần cơ sở hạ tầng phức tạp.</li></ul><p><strong>Ví dụ thực tế:</strong></p><ul><li>Điện thoại kết nối với tai nghe Bluetooth.</li><li>Đồng hồ thông minh (smartwatch) đồng bộ với điện thoại.</li><li>Bàn phím, chuột không dây kết nối với laptop.</li><li>Máy tính kết nối máy in qua cáp USB.</li><li>Thẻ NFC để thanh toán chạm (contactless payment).</li></ul><h3 id="_2-3-lan-–-mang-cuc-bo-local-area-network" tabindex="-1">2.3 LAN – Mạng cục bộ (Local Area Network) <a class="header-anchor" href="#_2-3-lan-–-mang-cuc-bo-local-area-network" aria-label="Permalink to &quot;2.3 LAN – Mạng cục bộ (Local Area Network)&quot;">​</a></h3><p><strong>LAN</strong> là mạng kết nối các thiết bị trong <strong>phạm vi địa lý giới hạn</strong> như tòa nhà, văn phòng, trường học.</p><p><strong>Đặc điểm:</strong></p><ul><li>Phạm vi: vài chục mét đến vài kilômét.</li><li>Tốc độ cao: <strong>100 Mbps đến 10 Gbps</strong>.</li><li>Độ trễ thấp.</li><li>Thuộc sở hữu và quản lý <strong>nội bộ</strong> (không phụ thuộc ISP).</li><li>Công nghệ: Ethernet (có dây), Wi-Fi/WLAN (không dây).</li><li>Thiết bị kết nối: Switch, Router, Access Point.</li></ul><p><strong>Phân loại con:</strong></p><table tabindex="0"><thead><tr><th>Loại</th><th>Tên</th><th>Mô tả</th></tr></thead><tbody><tr><td><strong>WLAN</strong></td><td>Wireless LAN</td><td>LAN không dây – dùng Wi-Fi (IEEE 802.11)</td></tr><tr><td><strong>VLAN</strong></td><td>Virtual LAN</td><td>LAN ảo – tách biệt logic trên cùng hạ tầng vật lý</td></tr></tbody></table><p><strong>Ví dụ thực tế:</strong></p><ul><li>Mạng máy tính phòng lab trường học.</li><li>Mạng văn phòng công ty.</li><li>Mạng gia đình (router Wi-Fi nhà bạn).</li><li>Mạng bệnh viện kết nối các khoa/phòng.</li></ul><h3 id="_2-4-man-–-mang-đo-thi-metropolitan-area-network" tabindex="-1">2.4 MAN – Mạng đô thị (Metropolitan Area Network) <a class="header-anchor" href="#_2-4-man-–-mang-đo-thi-metropolitan-area-network" aria-label="Permalink to &quot;2.4 MAN – Mạng đô thị (Metropolitan Area Network)&quot;">​</a></h3><p><strong>MAN</strong> là mạng kết nối các thiết bị trong <strong>phạm vi một thành phố hoặc vùng đô thị</strong>.</p><p><strong>Đặc điểm:</strong></p><ul><li>Phạm vi: <strong>vài kilômét đến vài chục kilômét</strong>.</li><li>Thường do <strong>tổ chức lớn hoặc nhà cung cấp dịch vụ</strong> quản lý.</li><li>Tốc độ cao hơn WAN, thấp hơn LAN.</li><li>Công nghệ: cáp quang, WiMAX, Ethernet tốc độ cao.</li></ul><p><strong>Ví dụ thực tế:</strong></p><ul><li>Mạng cáp truyền hình thành phố (CATV).</li><li>Mạng kết nối các chi nhánh ngân hàng trong một thành phố.</li><li>Mạng của cơ quan chính quyền thành phố (kết nối UBND các quận/phường).</li><li>Mạng camera an ninh toàn thành phố.</li><li>Mạng Internet học thuật kết nối các trường đại học trong thành phố (VINAREN).</li></ul><h3 id="_2-5-wan-–-mang-dien-rong-wide-area-network" tabindex="-1">2.5 WAN – Mạng diện rộng (Wide Area Network) <a class="header-anchor" href="#_2-5-wan-–-mang-dien-rong-wide-area-network" aria-label="Permalink to &quot;2.5 WAN – Mạng diện rộng (Wide Area Network)&quot;">​</a></h3><p><strong>WAN</strong> là mạng kết nối các thiết bị trên <strong>phạm vi rộng lớn</strong>: quốc gia, châu lục, hoặc toàn cầu.</p><p><strong>Đặc điểm:</strong></p><ul><li>Phạm vi: <strong>không giới hạn địa lý</strong>.</li><li>Tốc độ biến động – phụ thuộc vào đường truyền.</li><li>Độ trễ cao hơn LAN (do khoảng cách địa lý).</li><li>Thường sử dụng hạ tầng của <strong>ISP (nhà cung cấp dịch vụ Internet)</strong>.</li><li>Công nghệ: cáp quang biển/đất liền, vệ tinh, MPLS, SD-WAN.</li><li>Chi phí cao.</li></ul><p><strong>Ví dụ thực tế:</strong></p><ul><li><strong>Internet</strong> – WAN lớn nhất thế giới.</li><li>Mạng kết nối chi nhánh ngân hàng toàn quốc (VCB, Agribank...).</li><li>Mạng riêng của tập đoàn đa quốc gia (VPN site-to-site).</li><li>Mạng viễn thông di động (4G/5G) trên toàn quốc.</li></ul><h3 id="_2-6-phan-loai-theo-kieu-ket-noi-topology" tabindex="-1">2.6 Phân loại theo kiểu kết nối (Topology) <a class="header-anchor" href="#_2-6-phan-loai-theo-kieu-ket-noi-topology" aria-label="Permalink to &quot;2.6 Phân loại theo kiểu kết nối (Topology)&quot;">​</a></h3><p><strong>Topology</strong> (cấu trúc liên kết) mô tả cách các thiết bị được kết nối vật lý hoặc logic với nhau.</p><h4 id="🔵-mo-hinh-bus-tuyen-tinh" tabindex="-1">🔵 Mô hình Bus (Tuyến tính) <a class="header-anchor" href="#🔵-mo-hinh-bus-tuyen-tinh" aria-label="Permalink to &quot;🔵 Mô hình Bus (Tuyến tính)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PC1]---[PC2]---[PC3]---[PC4]---[PC5]</span></span>
<span class="line"><span>         ──────────────────────</span></span>
<span class="line"><span>              Cáp chung (Bus)</span></span></code></pre></div><ul><li>Tất cả thiết bị kết nối vào <strong>một đường cáp chung</strong>.</li><li>Dữ liệu lan toàn bộ cáp, chỉ thiết bị đích nhận.</li><li><strong>Ưu điểm:</strong> Đơn giản, ít cáp.</li><li><strong>Nhược điểm:</strong> Một điểm đứt → toàn mạng ngừng. Dễ xung đột dữ liệu.</li><li><strong>Hiện nay:</strong> Gần như không còn dùng.</li></ul><h4 id="🟢-mo-hinh-star-hinh-sao" tabindex="-1">🟢 Mô hình Star (Hình sao) <a class="header-anchor" href="#🟢-mo-hinh-star-hinh-sao" aria-label="Permalink to &quot;🟢 Mô hình Star (Hình sao)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         [PC1]</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>[PC4] --- [Switch/Hub] --- [PC2]</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>         [PC3]</span></span></code></pre></div><ul><li>Tất cả thiết bị kết nối vào <strong>một thiết bị trung tâm</strong> (Switch/Hub).</li><li><strong>Ưu điểm:</strong> Dễ quản lý, một thiết bị hỏng không ảnh hưởng thiết bị khác, dễ mở rộng.</li><li><strong>Nhược điểm:</strong> Nếu thiết bị trung tâm hỏng → toàn mạng ngừng. Tốn cáp hơn Bus.</li><li><strong>Hiện nay:</strong> <strong>Phổ biến nhất</strong> trong mạng LAN văn phòng, trường học, gia đình.</li></ul><h4 id="🟡-mo-hinh-ring-vong-tron" tabindex="-1">🟡 Mô hình Ring (Vòng tròn) <a class="header-anchor" href="#🟡-mo-hinh-ring-vong-tron" aria-label="Permalink to &quot;🟡 Mô hình Ring (Vòng tròn)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PC1] → [PC2]</span></span>
<span class="line"><span>  ↑           ↓</span></span>
<span class="line"><span>[PC4] ← [PC3]</span></span></code></pre></div><ul><li>Thiết bị kết nối thành <strong>vòng tròn khép kín</strong>.</li><li>Dữ liệu đi theo một chiều vòng quanh vòng.</li><li><strong>Ưu điểm:</strong> Không xung đột (dùng token), hiệu quả ở tải cao.</li><li><strong>Nhược điểm:</strong> Một thiết bị hỏng → toàn mạng ngừng. Khó thêm/bớt thiết bị.</li><li><strong>Hiện nay:</strong> Ít dùng (trừ mạng token ring cũ và một số mạng quang).</li></ul><h4 id="🔴-mo-hinh-mesh-luoi" tabindex="-1">🔴 Mô hình Mesh (Lưới) <a class="header-anchor" href="#🔴-mo-hinh-mesh-luoi" aria-label="Permalink to &quot;🔴 Mô hình Mesh (Lưới)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PC1] ─── [PC2]</span></span>
<span class="line"><span>  │  ╲   ╱  │</span></span>
<span class="line"><span>  │    ╳    │</span></span>
<span class="line"><span>  │  ╱   ╲  │</span></span>
<span class="line"><span>[PC4] ─── [PC3]</span></span></code></pre></div><ul><li>Mỗi thiết bị kết nối trực tiếp với <strong>nhiều thiết bị khác</strong>.</li><li><strong>Full Mesh:</strong> Mọi thiết bị kết nối với mọi thiết bị.</li><li><strong>Partial Mesh:</strong> Chỉ một số kết nối trực tiếp.</li><li><strong>Ưu điểm:</strong> Cực kỳ tin cậy – một đường hỏng vẫn có đường khác. Tốc độ cao.</li><li><strong>Nhược điểm:</strong> Rất tốn cáp và chi phí cao.</li><li><strong>Ứng dụng:</strong> Mạng Internet lõi (backbone), mạng quân sự, mạng cực quan trọng.</li></ul><h3 id="_2-7-phan-loai-theo-vai-tro-kien-truc-mang" tabindex="-1">2.7 Phân loại theo vai trò (Kiến trúc mạng) <a class="header-anchor" href="#_2-7-phan-loai-theo-vai-tro-kien-truc-mang" aria-label="Permalink to &quot;2.7 Phân loại theo vai trò (Kiến trúc mạng)&quot;">​</a></h3><h4 id="client-–-server-may-khach-–-may-chu" tabindex="-1">Client – Server (Máy khách – Máy chủ) <a class="header-anchor" href="#client-–-server-may-khach-–-may-chu" aria-label="Permalink to &quot;Client – Server (Máy khách – Máy chủ)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Client PC1] ─┐</span></span>
<span class="line"><span>[Client PC2] ──┼──► [Server trung tâm] ◄── Lưu dữ liệu, xử lý yêu cầu</span></span>
<span class="line"><span>[Client PC3] ─┘</span></span></code></pre></div><ul><li><strong>Server:</strong> Máy tính mạnh mẽ, lưu trữ dữ liệu/ứng dụng tập trung, phục vụ 24/7.</li><li><strong>Client:</strong> Máy tính người dùng, gửi yêu cầu đến server để được phục vụ.</li><li><strong>Ưu điểm:</strong> Quản lý tập trung dễ dàng, bảo mật tốt, dễ backup.</li><li><strong>Ứng dụng:</strong> Mạng doanh nghiệp, trường học có server, dịch vụ web (Google, Facebook là server, bạn là client).</li></ul><h4 id="peer-to-peer-p2p-–-ngang-hang" tabindex="-1">Peer-to-Peer (P2P – Ngang hàng) <a class="header-anchor" href="#peer-to-peer-p2p-–-ngang-hang" aria-label="Permalink to &quot;Peer-to-Peer (P2P – Ngang hàng)&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PC1] ↔ [PC2]</span></span>
<span class="line"><span>  ↕  ╲╱  ↕</span></span>
<span class="line"><span>[PC4] ↔ [PC3]</span></span></code></pre></div><ul><li>Mọi máy tính đều <strong>vừa là client vừa là server</strong>.</li><li>Chia sẻ tài nguyên trực tiếp, không qua trung gian.</li><li><strong>Ưu điểm:</strong> Đơn giản, không cần server đắt tiền, không điểm tắc nghẽn.</li><li><strong>Nhược điểm:</strong> Khó quản lý, bảo mật kém, không mở rộng tốt.</li><li><strong>Ứng dụng:</strong> Mạng gia đình nhỏ, BitTorrent (chia sẻ file P2P), blockchain.</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="tai-sao-mang-star-pho-bien-nhat-hien-nay" tabindex="-1">Tại sao mạng Star phổ biến nhất hiện nay? <a class="header-anchor" href="#tai-sao-mang-star-pho-bien-nhat-hien-nay" aria-label="Permalink to &quot;Tại sao mạng Star phổ biến nhất hiện nay?&quot;">​</a></h3><p>Hãy so sánh:</p><ul><li><strong>Mạng Bus (cũ):</strong> Nếu một cái dây bị đứt → cả lớp mất mạng. Phòng máy 30 PC, một sự cố nhỏ = 30 học sinh không học được.</li><li><strong>Mạng Star (hiện đại):</strong> PC1 bị hỏng cáp → chỉ PC1 mất mạng, 29 PC khác bình thường. Dễ phát hiện lỗi, dễ sửa.</li></ul><p>Chính vì tính <strong>chịu lỗi cao và dễ quản lý</strong>, mạng Star với Switch ở trung tâm đã trở thành tiêu chuẩn trong mọi mạng LAN hiện đại.</p><h3 id="lan-vs-internet-wan" tabindex="-1">LAN vs Internet (WAN) <a class="header-anchor" href="#lan-vs-internet-wan" aria-label="Permalink to &quot;LAN vs Internet (WAN)&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>LAN</th><th>Internet (WAN)</th></tr></thead><tbody><tr><td>Phạm vi</td><td>Tòa nhà, khuôn viên</td><td>Toàn cầu</td></tr><tr><td>Tốc độ</td><td>Rất cao (1-10 Gbps)</td><td>Thay đổi (10 Mbps - 1 Gbps tùy gói)</td></tr><tr><td>Độ trễ</td><td>Cực thấp (&lt; 1ms)</td><td>Cao hơn (10-100ms)</td></tr><tr><td>Chi phí</td><td>Thấp</td><td>Phải trả phí cho ISP</td></tr><tr><td>Quản lý</td><td>Bạn/tổ chức của bạn</td><td>ISP + nhiều tổ chức</td></tr><tr><td>Bảo mật</td><td>Tương đối dễ kiểm soát</td><td>Phức tạp hơn nhiều</td></tr></tbody></table><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="du-lieu-đi-qua-nhieu-loai-mang" tabindex="-1">Dữ liệu đi qua nhiều loại mạng <a class="header-anchor" href="#du-lieu-đi-qua-nhieu-loai-mang" aria-label="Permalink to &quot;Dữ liệu đi qua nhiều loại mạng&quot;">​</a></h3><p><strong>Tình huống:</strong> Học sinh tại trường học (LAN) xem video trên YouTube (máy chủ ở Mỹ, WAN/Internet).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Máy tính học sinh]</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Switch – mạng LAN trường] (LAN – tốc độ cao, độ trễ thấp)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Router trường học]  ← Ranh giới LAN / WAN</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Mạng của ISP Việt Nam] (MAN/WAN – cáp quang nội địa)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Cáp biển quốc tế] (WAN – cáp quang xuyên Thái Bình Dương)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Mạng Internet Mỹ]</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>[Máy chủ YouTube] → Gửi video về theo đường ngược lại</span></span></code></pre></div><blockquote><p>Dữ liệu đi qua <strong>LAN → WAN → WAN</strong> để từ phòng học đến máy chủ YouTube ở Mỹ và quay trở lại.</p></blockquote><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-nhan-biet-loai-mang-tu-tinh-huong" tabindex="-1">Ví dụ 1 – Nhận biết loại mạng từ tình huống <a class="header-anchor" href="#vi-du-1-–-nhan-biet-loai-mang-tu-tinh-huong" aria-label="Permalink to &quot;Ví dụ 1 – Nhận biết loại mạng từ tình huống&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tình huống</th><th>Loại mạng</th></tr></thead><tbody><tr><td>Bạn kết nối tai nghe Bluetooth với điện thoại</td><td>PAN</td></tr><tr><td>30 máy tính trong phòng lab được kết nối với nhau</td><td>LAN</td></tr><tr><td>Các chi nhánh BIDV trên toàn thành phố HCM kết nối với nhau</td><td>MAN</td></tr><tr><td>Bạn truy cập Wikipedia từ Việt Nam</td><td>WAN (Internet)</td></tr><tr><td>Router Wi-Fi nhà bạn tạo ra</td><td>LAN (WLAN)</td></tr><tr><td>Nhân viên từ xa VPN vào mạng công ty</td><td>WAN (VPN qua Internet)</td></tr></tbody></table><h3 id="vi-du-2-–-nhan-biet-topology-tu-mo-ta" tabindex="-1">Ví dụ 2 – Nhận biết topology từ mô tả <a class="header-anchor" href="#vi-du-2-–-nhan-biet-topology-tu-mo-ta" aria-label="Permalink to &quot;Ví dụ 2 – Nhận biết topology từ mô tả&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mô tả</th><th>Topology</th></tr></thead><tbody><tr><td>20 máy tính đều cắm vào một switch trung tâm</td><td>Star</td></tr><tr><td>Máy tính kết nối dây theo dạng đầu nối đầu, tất cả dùng chung cáp</td><td>Bus</td></tr><tr><td>Mỗi router biên của ISP kết nối trực tiếp với ít nhất 3 router khác</td><td>Mesh</td></tr><tr><td>Thiết bị gửi token theo vòng trước khi truyền dữ liệu</td><td>Ring</td></tr></tbody></table><h3 id="vi-du-3-–-thiet-ke-mang-truong-hoc" tabindex="-1">Ví dụ 3 – Thiết kế mạng trường học <a class="header-anchor" href="#vi-du-3-–-thiet-ke-mang-truong-hoc" aria-label="Permalink to &quot;Ví dụ 3 – Thiết kế mạng trường học&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trường THPT với 40 phòng học:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Internet/ISP - 1 Gbps fiber]</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>   [Modem quang]</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>[Router trung tâm] ← WAN kết thúc ở đây, LAN bắt đầu</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>[Core Switch – tốc độ cao]  ← Trung tâm mạng Star cấp 1</span></span>
<span class="line"><span>    /    |    \\</span></span>
<span class="line"><span>[SW dãy A] [SW dãy B] [SW dãy C]  ← Switch cấp 2 (Star cấp 2)</span></span>
<span class="line"><span>  / | \\    / | \\    / | \\</span></span>
<span class="line"><span>[Phòng] [Phòng]...  ← Mỗi phòng là một LAN nhỏ (Star cấp 3)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Kết quả: Mạng hình cây (Tree = Star nhiều cấp) – phổ biến trong tổ chức lớn</span></span></code></pre></div><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-cac-loai-mang-theo-pham-vi" tabindex="-1">So sánh các loại mạng theo phạm vi <a class="header-anchor" href="#so-sanh-cac-loai-mang-theo-pham-vi" aria-label="Permalink to &quot;So sánh các loại mạng theo phạm vi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>PAN</th><th>LAN</th><th>MAN</th><th>WAN</th></tr></thead><tbody><tr><td><strong>Phạm vi</strong></td><td>&lt; 10m</td><td>100m – vài km</td><td>Vài km – 100km</td><td>Toàn cầu</td></tr><tr><td><strong>Tốc độ điển hình</strong></td><td>1–100 Mbps</td><td>100Mbps–10Gbps</td><td>10Mbps–1Gbps</td><td>10Mbps–100Gbps</td></tr><tr><td><strong>Sở hữu</strong></td><td>Cá nhân</td><td>Tổ chức/gia đình</td><td>Thành phố/tổ chức</td><td>ISP/nhiều tổ chức</td></tr><tr><td><strong>Chi phí thiết lập</strong></td><td>Rất thấp</td><td>Thấp–Trung bình</td><td>Cao</td><td>Rất cao</td></tr><tr><td><strong>Công nghệ</strong></td><td>Bluetooth, USB</td><td>Ethernet, Wi-Fi</td><td>Cáp quang, WiMAX</td><td>Cáp biển, vệ tinh</td></tr></tbody></table><h3 id="so-sanh-cac-topology" tabindex="-1">So sánh các topology <a class="header-anchor" href="#so-sanh-cac-topology" aria-label="Permalink to &quot;So sánh các topology&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Topology</th><th>Điểm hỏng?</th><th>Dễ mở rộng?</th><th>Tốn cáp?</th><th>Phổ biến ngày nay?</th></tr></thead><tbody><tr><td><strong>Bus</strong></td><td>Đứt cáp → cả mạng ngừng</td><td>Khó</td><td>Ít</td><td>Không</td></tr><tr><td><strong>Star</strong></td><td>Switch hỏng → cả mạng ngừng</td><td>Dễ</td><td>Trung bình</td><td>Rất phổ biến</td></tr><tr><td><strong>Ring</strong></td><td>1 node hỏng → cả vòng ngừng</td><td>Khó</td><td>Trung bình</td><td>Hiếm</td></tr><tr><td><strong>Mesh</strong></td><td>Rất ít điểm hỏng</td><td>Khó</td><td>Rất nhiều</td><td>Mạng backbone</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>📱 <strong>PAN</strong> = Personal Area Network = Bluetooth, vài mét xung quanh người</li><li>🏢 <strong>LAN</strong> = Local Area Network = trong tòa nhà/khuôn viên = Ethernet, Wi-Fi</li><li>🏙️ <strong>MAN</strong> = Metropolitan Area Network = trong thành phố = cáp quang đô thị</li><li>🌍 <strong>WAN</strong> = Wide Area Network = toàn quốc/toàn cầu = Internet</li><li>⭐ <strong>Star topology</strong> = phổ biến nhất hiện nay = Switch ở giữa, PC tỏa ra</li><li>📏 <strong>Bus topology</strong> = cáp chung, cũ, không còn dùng</li><li>🔄 <strong>Ring topology</strong> = vòng tròn, token, ít dùng</li><li>🕸️ <strong>Mesh topology</strong> = kết nối nhiều chiều, dùng cho mạng backbone</li><li>🖥️ <strong>Client-Server</strong> = có server tập trung = doanh nghiệp, trường học</li><li>🤝 <strong>P2P (Peer-to-Peer)</strong> = ngang hàng, chia sẻ trực tiếp = BitTorrent</li><li>🏠 LAN nhà bạn: Router (kết nối WAN) → Switch/AP → Thiết bị = <strong>Star topology</strong></li><li>📶 WLAN = Wireless LAN = Wi-Fi (IEEE 802.11a/b/g/n/ac/ax)</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-ghep-cap" tabindex="-1">Câu 1 (Dễ): Ghép cặp <a class="header-anchor" href="#cau-1-de-ghep-cap" aria-label="Permalink to &quot;Câu 1 (Dễ): Ghép cặp&quot;">​</a></h3><blockquote><p>Ghép loại mạng với ví dụ phù hợp:</p></blockquote><table tabindex="0"><thead><tr><th>Ví dụ</th><th>Loại mạng</th></tr></thead><tbody><tr><td>A. Internet</td><td>1. PAN</td></tr><tr><td>B. Mạng phòng máy tính trường</td><td>2. LAN</td></tr><tr><td>C. Smartwatch kết nối điện thoại</td><td>3. MAN</td></tr><tr><td>D. Mạng cáp TV toàn thành phố</td><td>4. WAN</td></tr></tbody></table><p><strong>Đáp án:</strong> A-4, B-2, C-1, D-3</p><hr><h3 id="cau-2-de-trac-nghiem-topology" tabindex="-1">Câu 2 (Dễ): Trắc nghiệm topology <a class="header-anchor" href="#cau-2-de-trac-nghiem-topology" aria-label="Permalink to &quot;Câu 2 (Dễ): Trắc nghiệm topology&quot;">​</a></h3><blockquote><p>Trong mạng phòng máy tính gồm 25 PC, tất cả đều kết nối vào một Switch 24 cổng ở trung tâm. Đây là topology gì? A. Bus B. Ring C. Star D. Mesh</p></blockquote><p><strong>Đáp án: C – Star</strong></p><p><strong>Giải thích:</strong> Khi tất cả thiết bị kết nối vào <strong>một thiết bị trung tâm</strong> (ở đây là Switch), đó là topology hình sao (Star). Đây là cấu trúc phổ biến nhất trong mạng LAN hiện đại.</p><hr><h3 id="cau-3-trung-binh-phan-tich-uu-nhuoc-điem" tabindex="-1">Câu 3 (Trung bình): Phân tích ưu/nhược điểm <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-uu-nhuoc-điem" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích ưu/nhược điểm&quot;">​</a></h3><blockquote><p>Trường học A đang dùng mạng Bus (tất cả máy tính nối vào một cáp chung). Giáo viên phàn nàn rằng mỗi khi một máy hỏng cáp là cả phòng mất mạng. Bạn đề xuất chuyển sang topology nào? Tại sao?</p></blockquote><p><strong>Đáp án:</strong> Đề xuất chuyển sang <strong>Star topology</strong> (mạng hình sao).</p><p><strong>Lý do:</strong></p><ul><li>Trong mạng Star, mỗi máy tính kết nối <strong>độc lập</strong> vào Switch trung tâm.</li><li>Nếu một máy hỏng cáp → <strong>chỉ máy đó mất mạng</strong>, các máy khác không ảnh hưởng.</li><li>Dễ phát hiện lỗi (xem đèn trạng thái cổng switch để biết cổng nào lỗi).</li><li>Dễ thêm máy mới (chỉ cần cắm thêm dây vào switch có cổng trống).</li><li><strong>Chi phí nâng cấp:</strong> Mua thêm Switch + thêm cáp từ mỗi PC đến Switch.</li></ul><hr><h3 id="cau-4-trung-binh-xac-đinh-loai-mang-trong-thuc-te" tabindex="-1">Câu 4 (Trung bình): Xác định loại mạng trong thực tế <a class="header-anchor" href="#cau-4-trung-binh-xac-đinh-loai-mang-trong-thuc-te" aria-label="Permalink to &quot;Câu 4 (Trung bình): Xác định loại mạng trong thực tế&quot;">​</a></h3><blockquote><p>Ngân hàng Vietcombank có:</p><ul><li>100 máy tính trong trụ sở chính ở Hà Nội (kết nối qua switch)</li><li>500 chi nhánh trên toàn quốc, mỗi chi nhánh có mạng nội bộ</li><li>Tất cả chi nhánh kết nối với trụ sở chính qua đường truyền riêng của nhà mạng</li></ul><p>Xác định loại mạng trong từng phạm vi.</p></blockquote><p><strong>Đáp án:</strong></p><table tabindex="0"><thead><tr><th>Phạm vi</th><th>Loại mạng</th><th>Giải thích</th></tr></thead><tbody><tr><td>100 máy trong trụ sở chính</td><td><strong>LAN</strong></td><td>Mạng cục bộ trong một tòa nhà</td></tr><tr><td>Mạng nội bộ mỗi chi nhánh</td><td><strong>LAN</strong></td><td>Mạng cục bộ trong mỗi chi nhánh</td></tr><tr><td>Kết nối toàn bộ chi nhánh trên toàn quốc</td><td><strong>WAN</strong></td><td>Mạng diện rộng, phạm vi toàn quốc</td></tr></tbody></table><hr><h3 id="cau-5-van-dung-thiet-ke-mang" tabindex="-1">Câu 5 (Vận dụng): Thiết kế mạng <a class="header-anchor" href="#cau-5-van-dung-thiet-ke-mang" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Thiết kế mạng&quot;">​</a></h3><blockquote><p>Bạn cần thiết kế mạng cho văn phòng nhỏ gồm 10 PC. Yêu cầu:</p><ul><li>Nếu một PC hỏng, các PC khác vẫn hoạt động bình thường.</li><li>Dễ thêm PC mới.</li><li>Chi phí cáp mạng tiết kiệm.</li></ul><p>Hãy chọn topology phù hợp, liệt kê thiết bị cần thiết, và vẽ sơ đồ đơn giản.</p></blockquote><p><strong>Đáp án:</strong></p><p><strong>Topology được chọn: Star (hình sao)</strong></p><p><strong>Lý do:</strong> Đáp ứng cả 3 yêu cầu:</p><ul><li>PC hỏng không ảnh hưởng PC khác ✅</li><li>Thêm PC chỉ cần thêm cáp từ PC đến switch ✅</li><li>Ít cáp hơn Mesh, mỗi PC chỉ cần 1 đoạn cáp ✅</li></ul><p><strong>Thiết bị cần mua:</strong></p><table tabindex="0"><thead><tr><th>Thiết bị</th><th>Số lượng</th><th>Vai trò</th></tr></thead><tbody><tr><td>Switch 16 cổng</td><td>1</td><td>Thiết bị trung tâm, kết nối tất cả PC</td></tr><tr><td>Cáp Ethernet Cat6</td><td>10 đoạn</td><td>Mỗi đoạn từ 1 PC đến Switch</td></tr><tr><td>Router</td><td>1</td><td>Kết nối mạng LAN với Internet</td></tr></tbody></table><p><strong>Sơ đồ:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          [Internet]</span></span>
<span class="line"><span>               |</span></span>
<span class="line"><span>           [Router]</span></span>
<span class="line"><span>               |</span></span>
<span class="line"><span>          [Switch 16 cổng]</span></span>
<span class="line"><span>         /  |  |  |  |  \\</span></span>
<span class="line"><span>       PC1 PC2 PC3 PC4 PC5...PC10</span></span></code></pre></div><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-internet-voi-lan" tabindex="-1">❌ Lỗi 1: Nhầm Internet với LAN <a class="header-anchor" href="#❌-loi-1-nham-internet-voi-lan" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Internet với LAN&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mạng nhà tôi cũng là một phần của Internet.&quot;</p><p><strong>Đúng:</strong> Mạng nhà bạn là <strong>LAN</strong> (Local Area Network) – mạng nội bộ riêng của nhà bạn. LAN của nhà bạn kết nối <strong>ra</strong> Internet qua Router và ISP, nhưng LAN và Internet là hai thứ <strong>khác nhau</strong>. Dữ liệu trong LAN (PC nói chuyện với PC cùng nhà) không phải qua Internet.</p><hr><h3 id="❌-loi-2-nham-man-voi-wan" tabindex="-1">❌ Lỗi 2: Nhầm MAN với WAN <a class="header-anchor" href="#❌-loi-2-nham-man-voi-wan" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm MAN với WAN&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mạng kết nối các quận trong TP.HCM là WAN.&quot;</p><p><strong>Đúng:</strong> Mạng kết nối trong phạm vi <strong>một thành phố</strong> là <strong>MAN</strong> (Metropolitan Area Network). WAN mới là mạng phạm vi <strong>quốc gia hoặc toàn cầu</strong>. Ranh giới: thành phố = MAN, toàn quốc/thế giới = WAN.</p><hr><h3 id="❌-loi-3-nghi-star-topology-khong-co-điem-hong" tabindex="-1">❌ Lỗi 3: Nghĩ Star topology không có điểm hỏng <a class="header-anchor" href="#❌-loi-3-nghi-star-topology-khong-co-điem-hong" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ Star topology không có điểm hỏng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mạng Star hoàn toàn không bị ảnh hưởng khi có hỏng hóc.&quot;</p><p><strong>Đúng:</strong> Mạng Star vẫn có <strong>điểm hỏng tập trung</strong> – đó là thiết bị trung tâm (Switch). Nếu Switch hỏng, <strong>toàn bộ mạng</strong> bị ngắt. Ưu điểm của Star là một <strong>thiết bị đầu cuối</strong> (PC) hỏng không ảnh hưởng các PC khác – không phải là &quot;không bao giờ sập&quot;.</p><hr><h3 id="❌-loi-4-nham-wlan-voi-wi-fi" tabindex="-1">❌ Lỗi 4: Nhầm WLAN với Wi-Fi <a class="header-anchor" href="#❌-loi-4-nham-wlan-voi-wi-fi" aria-label="Permalink to &quot;❌ Lỗi 4: Nhầm WLAN với Wi-Fi&quot;">​</a></h3><p><strong>Sai:</strong> &quot;WLAN và Wi-Fi là hai công nghệ khác nhau hoàn toàn.&quot;</p><p><strong>Đúng:</strong> <strong>WLAN (Wireless LAN)</strong> là tên gọi chung cho mạng LAN không dây. <strong>Wi-Fi</strong> là tên thương mại của chuẩn <strong>IEEE 802.11</strong> – công nghệ cụ thể được dùng để xây dựng WLAN. Nói đơn giản: Wi-Fi là cách thực hiện WLAN phổ biến nhất hiện nay. Mọi mạng Wi-Fi đều là WLAN, nhưng về lý thuyết WLAN có thể dùng công nghệ khác Wi-Fi.</p><hr><h3 id="❌-loi-5-nham-p2p-networking-voi-p2p-file-sharing" tabindex="-1">❌ Lỗi 5: Nhầm P2P networking với P2P file sharing <a class="header-anchor" href="#❌-loi-5-nham-p2p-networking-voi-p2p-file-sharing" aria-label="Permalink to &quot;❌ Lỗi 5: Nhầm P2P networking với P2P file sharing&quot;">​</a></h3><p><strong>Sai:</strong> &quot;P2P là phần mềm tải phim lậu.&quot;</p><p><strong>Đúng:</strong> <strong>P2P (Peer-to-Peer)</strong> là <strong>kiến trúc mạng</strong> trong đó các thiết bị giao tiếp trực tiếp không qua server trung tâm. BitTorrent (tải file) và blockchain (tiền điện tử) dùng kiến trúc P2P, nhưng P2P không đồng nghĩa với tải file lậu. P2P cũng được dùng cho mục đích hợp pháp như chia sẻ tài liệu trong mạng nội bộ hay hệ thống blockchain.</p>`,144)])])}const u=t(o,[["render",r]]);export{d as __pageData,u as default};
